1	//! # 阶段 2：块解析
2	//!
3	//! 将块转换为 ScriptNode。按指令域拆分为子模块：
4	//! - `display`: 显示指令（changeBG/changeScene/show/hide + 过渡效果）
5	//! - `control`: 控制流（goto/callScript/conditional/set/wait/choice table）
6	//! - `dialogue`: 对话与文本（chapter/extend）
7	//! - `misc`: 杂项（audio/sceneEffect/titleCard/cutscene）
8	
9	mod control;
10	mod dialogue;
11	mod display;
12	mod misc;
13	
14	use super::{
15	    helpers::{parse_dialogue, starts_with_ignore_case},
16	    inline_tags::parse_inline_tags,
17	    phase1::Block,
18	};
19	use crate::{error::ParseError, script::ast::ScriptNode};
20	
21	/// 阶段 2 解析器
22	pub(super) struct Phase2Parser {
23	    /// 解析警告（非致命错误）
24	    pub warnings: Vec<String>,
25	}
26	
27	impl Phase2Parser {
28	    pub(super) fn new() -> Self {
29	        Self {
30	            warnings: Vec::new(),
31	        }
32	    }
33	
34	    pub(super) fn reset_state(&mut self) {
35	        self.warnings.clear();
36	    }
37	
38	    /// 解析单个块
39	    pub(super) fn parse_block(&mut self, block: Block) -> Result<Option<ScriptNode>, ParseError> {
40	        match block {
41	            Block::SingleLine { line, line_number } => self.parse_single_line(&line, line_number),
42	            Block::Table { lines, start_line } => self.parse_table(&lines, start_line),
43	            Block::Conditional { lines, start_line } => self.parse_conditional(&lines, start_line),
44	        }
45	    }
46	
47	    /// 解析单行内容 — 按前缀分发到各子模块
48	    pub(super) fn parse_single_line(
49	        &mut self,
50	        line: &str,
51	        line_number: usize,
52	    ) -> Result<Option<ScriptNode>, ParseError> {
53	        let (line, no_wait) = strip_arrow_suffix(line.trim());
54	        let line = line.trim();
55	
56	        // Markdown 注释块
57	        if line.starts_with('>') {
58	            return Ok(None);
59	        }
60	
61	        // 章节标记 (# Title)
62	        if line.starts_with('#') {
63	            return Ok(self.parse_chapter(line));
64	        }
65	
66	        // 标签定义 (**label_name**)
67	        if line.starts_with("**") && line.ends_with("**") && line.len() > 4 {
68	            let name = &line[2..line.len() - 2];
69	            if !name.contains('*') {
70	                return Ok(Some(ScriptNode::Label {
71	                    name: name.trim().to_string(),
72	                }));
73	            }
74	        }
75	
76	        // --- 指令分发（大小写不敏感）---
77	
78	        // 显示指令
79	        if starts_with_ignore_case(line, "changebg") {
80	            return self.parse_change_bg(line, line_number);
81	        }
82	        if starts_with_ignore_case(line, "changescene") {
83	            return self.parse_change_scene(line, line_number);
84	        }
85	        if starts_with_command(line, "show") {
86	            return self.parse_show(line, line_number);
87	        }
88	        if starts_with_command(line, "hide") {
89	            return self.parse_hide(line, line_number);
90	        }
91	
92	        // 控制流指令
93	        if starts_with_ignore_case(line, "goto") {
94	            return self.parse_goto(line, line_number);
95	        }
96	        if starts_with_ignore_case(line, "callscript") {
97	            return self.parse_call_script(line, line_number);
98	        }
99	        if starts_with_ignore_case(line, "returnfromscript") {
100	            return Ok(Some(ScriptNode::ReturnFromScript));
101	        }
102	        if starts_with_ignore_case(line, "fullrestart") {
103	            return Ok(Some(ScriptNode::FullRestart));
104	        }
105	        if starts_with_ignore_case(line, "set ") {
106	            return self.parse_set_var(line, line_number);
107	        }
108	        if starts_with_command(line, "wait") {
109	            return self.parse_wait(line, line_number);
110	        }
111	        if starts_with_ignore_case(line, "pause")
112	            && (line.len() == 5 || line.as_bytes().get(5).is_none_or(u8::is_ascii_whitespace))
113	        {
114	            return Ok(Some(ScriptNode::Pause));
115	        }
116	        if starts_with_ignore_case(line, "clearcharacters") {
117	            return Ok(Some(ScriptNode::ClearCharacters));
118	        }
119	
120	        // 音频指令（简单变体内联，复杂解析委托到 misc）
121	        if starts_with_ignore_case(line, "stopbgm") {
122	            return Ok(Some(ScriptNode::StopBgm));
123	        }
124	        if starts_with_ignore_case(line, "bgmunduck") {
125	            return Ok(Some(ScriptNode::BgmUnduck));
126	        }
127	        if starts_with_ignore_case(line, "bgmduck") {
128	            return Ok(Some(ScriptNode::BgmDuck));
129	        }
130	
131	        // UI 指令
132	        if starts_with_ignore_case(line, "textboxhide") {
133	            return Ok(Some(ScriptNode::TextBoxHide));
134	        }
135	        if starts_with_ignore_case(line, "textboxshow") {
136	            return Ok(Some(ScriptNode::TextBoxShow));
137	        }
138	        if starts_with_ignore_case(line, "textboxclear") {
139	            return Ok(Some(ScriptNode::TextBoxClear));
140	        }
141	
142	        // 杂项指令
143	        if starts_with_ignore_case(line, "sceneeffect") {
144	            return self.parse_scene_effect(line, line_number);
145	        }
146	        if starts_with_ignore_case(line, "titlecard") {
147	            return self.parse_title_card(line, line_number);
148	        }
149	        if starts_with_ignore_case(line, "cutscene") {
150	            return self.parse_cutscene(line, line_number);
151	        }
152	        if starts_with_ignore_case(line, "requestui") {
153	            return self.parse_request_ui(line, line_number);
154	        }
155	        if starts_with_ignore_case(line, "textmode") {
156	            return self.parse_text_mode(line, line_number);
157	        }
158	        if starts_with_ignore_case(line, "showmap") {
159	            return self.parse_show_map(line, line_number);
160	        }
161	        if starts_with_ignore_case(line, "callgame") {
162	            return self.parse_call_game(line, line_number);
163	        }
164	        if starts_with_command(line, "extend") {
165	            return self.parse_extend(line, line_number, no_wait);
166	        }
167	
168	        // HTML audio 标签
169	        if line.starts_with("<audio") {
170	            return self.parse_audio(line, line_number);
171	        }
172	
173	        // 对话/旁白
174	        if let Some((speaker, raw_content)) = parse_dialogue(line) {
175	            let (content, inline_effects) = parse_inline_tags(&raw_content);
176	            return Ok(Some(ScriptNode::Dialogue {
177	                speaker,
178	                content,
179	                inline_effects,
180	                no_wait,
181	            }));
182	        }
183	
184	        // 未知行
185	        self.warnings.push(format!(
186	            "第 {line_number} 行：无法识别的内容，已跳过: {line}"
187	        ));
188	        Ok(None)
189	    }
190	}
191	
192	/// 检测并剥离行尾 `-->` 修饰符
193	fn strip_arrow_suffix(line: &str) -> (&str, bool) {
194	    let trimmed = line.trim_end();
195	    if let Some(before) = trimmed.strip_suffix("-->") {
196	        (before, true)
197	    } else {
198	        (line, false)
199	    }
200	}
201	
202	fn starts_with_command(line: &str, command: &str) -> bool {
203	    let line = line.trim_start();
204	    if line.len() < command.len() || !starts_with_ignore_case(line, command) {
205	        return false;
206	    }
207	    let next = line[command.len()..].chars().next();
208	    match next {
209	        None => true,
210	        Some(ch) => ch.is_whitespace() || ch == '<',
211	    }
212	}
213	
214	pub(super) fn parse_markdown_link(input: &str) -> Option<(&str, &str, &str)> {
215	    let trimmed = input.trim_start();
216	    if !trimmed.starts_with('[') {
217	        return None;
218	    }
219	
220	    let label_end = trimmed.find(']')?;
221	    let label = &trimmed[1..label_end];
222	    if label.trim().is_empty() {
223	        return None;
224	    }
225	
226	    let after_label = &trimmed[label_end + 1..];
227	    if !after_label.starts_with('(') {
228	        return None;
229	    }
230	    let path_end = after_label.find(')')?;
231	    let path = &after_label[1..path_end];
232	    if path.trim().is_empty() {
233	        return None;
234	    }
235	
236	    let rest = &after_label[path_end + 1..];
237	    Some((label.trim(), path.trim(), rest))
238	}
