11	    pub(super) fn parse_chapter(&self, line: &str) -> Option<ScriptNode> {
12	        let level = line.chars().take_while(|&c| c == '#').count() as u8;
13	        if level == 0 || level > 6 {
14	            return None;
15	        }
16	
17	        let title = line[level as usize..].trim();
18	        if title.is_empty() {
19	            return None;
20	        }
21	
22	        Some(ScriptNode::Chapter {
23	            title: title.to_string(),
24	            level,
25	        })
26	    }
