29	    ///
30	    /// 语法: `extend "追加文本"`
31	    pub(super) fn parse_extend(
32	        &self,
33	        line: &str,
34	        line_number: usize,
35	        no_wait: bool,
36	    ) -> Result<Option<ScriptNode>, ParseError> {
37	        let content_part = line
38	            .get("extend".len()..)
39	            .map(str::trim)
40	            .filter(|s| !s.is_empty())
41	            .ok_or_else(|| ParseError::MissingParameter {
42	                line: line_number,
43	                command: "extend".to_string(),
44	                param: "quoted text".to_string(),
45	            })?;
46	
47	        let raw_content =
48	            extract_quoted_content(content_part).ok_or_else(|| ParseError::MissingParameter {
49	                line: line_number,
50	                command: "extend".to_string(),
51	                param: "quoted text (use \"...\")".to_string(),
52	            })?;
53	
54	        let (content, inline_effects) = parse_inline_tags(raw_content);
55	
56	        Ok(Some(ScriptNode::Extend {
57	            content,
58	            inline_effects,
59	            no_wait,
60	        }))
61	    }
62	}
