526	/// 解析 requestUI 参数列表：`key1: value1, key2: "str"`
527	fn parse_request_ui_params(
528	    args_str: &str,
529	    line_number: usize,
530	) -> Result<Vec<(String, Expr)>, ParseError> {
531	    let mut params = Vec::new();
532	    if args_str.trim().is_empty() {
533	        return Ok(params);
534	    }
535	
536	    for part in split_params(args_str) {
537	        let part = part.trim();
538	        if part.is_empty() {
539	            continue;
540	        }
541	        let colon_pos = part.find(':').ok_or_else(|| ParseError::InvalidParameter {
542	            line: line_number,
543	            param: "params".to_string(),
544	            message: format!("parameter must be in 'key: value' format, got: '{part}'"),
545	        })?;
546	        let key = part[..colon_pos].trim().to_string();
547	        let value_str = part[colon_pos + 1..].trim();
548	        let expr = parse_expression(value_str, line_number)?;
549	        params.push((key, expr));
550	    }
551	
552	    Ok(params)
553	}
